import {
  CREDIT_COST_PER_ANONYMIZATION,
  CREDIT_COST_PER_INSPIRATION,
} from "./credits";
import { internal } from "./_generated/api";
import { POSTHOG_EVENTS } from "../src/features/posthog/posthog-events";
