        BEGIN {
          $| = 1;
          open(LOG, ">>", $ENV{LOG}) or die "open $ENV{LOG}: $!";
          select((select(LOG), $| = 1)[0]);
        }
        my $c = $_;
        $c =~ s/\033\[[0-9;?]*[a-zA-Z]//g;
        $c =~ s/\r/\n/g;
        print LOG $c;
        print "$ENV{PREFIX} $_";
