  objects?: Array<DrawingObject>;
};

export function createDrawingDocument(
  input: CreateDrawingDocumentInput = {},
): DrawingDocument {
  return DrawingDocumentSchema.parse({
    version: DRAWING_DOCUMENT_VERSION,
    width: DRAWING_DOCUMENT_WIDTH,
