export const createDrawing = mutation({
  args: {
    orgSlug: v.string(),
    title: v.string(),
    previewUrl: v.string(),
    drawingDocument: drawingDocumentValidator,
  },
  handler: async (ctx, args) => {
    const appCtx = ctx as unknown as AppCtx;
    const { org } = await requireOrg(appCtx, args.orgSlug);
    const previewUrl = args.previewUrl.trim();
    if (!previewUrl) throw new Error("Drawing preview is required");

    const limits = await getOrgPlanLimits(appCtx, org.id);
    const inspirations = await ctx.db
      .query("inspirations")
      .withIndex("by_organization", (q) => q.eq("organizationId", org.id))
      .collect();
    const currentCount = inspirations.filter(
      (inspiration) => !inspiration.deletedAt,
    ).length;
    if (currentCount >= limits.maxInspirations) {
      throw new Error(
        `You have reached your limit of ${limits.maxInspirations} inspirations. Upgrade to create more.`,
      );
    }

    const now = Date.now();
    const image = storedImage(previewUrl, "image/png");
    const hasPlaceholder = args.drawingDocument.objects.some(
      (object) => object.type === "person",
    );
    const id = await ctx.db.insert("inspirations", {
      organizationId: org.id,
      title: args.title.trim() || "Drawing inspiration",
      description:
        "A hand-drawn thumbnail composition to use as visual inspiration.",
      image,
      images: [image],
      categories: ["Other"],
      hasPlaceholder,
      drawingDocument: args.drawingDocument,
      isPublic: false,
      adminReview: REVIEW_STATUS.DENY,
      createdAt: now,
      updatedAt: now,
    });

    const created = await ctx.db.get(id);
    if (!created) throw new Error("Drawing inspiration not found");
    return toInspirationRow(created);
  },
});

