        ...history.document,
        objects: [...history.document.objects, object],
      });
      setSelectedObjectId(object.id);
      setTool("select");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Image upload failed");
    } finally {
      if (imageInputRef.current) imageInputRef.current.value = "";
    }
