            onClick={history.redo}
          >
            <Redo2 className="size-4" />
          </Button>
          <span className="text-muted-foreground hidden items-center gap-1.5 text-xs lg:flex">
            {isDirty ? (
              "Unsaved"
            ) : (
              <>
                <Check className="size-3.5" /> Saved
              </>
            )}
          </span>
          <Button
            type="button"
            variant="ghost"
            className="hidden sm:inline-flex"
            disabled={isSaving}
            onClick={handleCancel}
          >
            Cancel
          </Button>
          <Button
            type="button"
            className="active:scale-[0.96] transition-transform"
            disabled={isSaving || isUploadingImage}
            onClick={() => void handleSave()}
          >
            {isSaving ? <Spinner className="size-4" /> : <Save className="size-4" />}
            <span className="hidden sm:inline">Save inspiration</span>
            <span className="sm:hidden">Save</span>
          </Button>
        </div>
      </header>

      <section className="relative flex min-h-0 flex-1 flex-col items-center overflow-auto px-4 pt-20 pb-16 sm:px-8">
        <div className="absolute top-3 left-1/2 z-20 max-w-[calc(100vw-2rem)] -translate-x-1/2 overflow-x-auto p-1">
          <DrawingToolbar
            tool={tool}
            templates={STARTER_TEMPLATES.map((template) => ({ ...template }))}
            disabled={isSaving || isUploadingImage}
            onToolChange={(nextTool) => {
              setTool(nextTool);
              setEditingTextId(null);
            }}
            onInsertImage={() => imageInputRef.current?.click()}
            onInsertPerson={insertPerson}
            onApplyTemplate={applyTemplate}
          />
        </div>

        <div className="my-auto w-[min(1120px,calc(100vw-3rem))] shrink-0">
          <DrawingCanvas
            document={history.document}
            tool={tool}
            selectedObjectId={selectedObjectId}
            editingTextId={editingTextId}
            onSelectObject={setSelectedObjectId}
            onToolChange={setTool}
            onPreviewDocument={history.preview}
            onCommitDocument={commitDocument}
            onStartTextEditing={setEditingTextId}
            onFinishTextEditing={() => setEditingTextId(null)}
          />
        </div>

        {selectedObject && !editingTextId ? (
          <div className="absolute top-20 right-4 z-20 hidden xl:block">
            <DrawingProperties
              object={selectedObject}
              onChange={updateSelectedObject}
              onDuplicate={duplicateSelectedObject}
              onDelete={removeSelectedObject}
            />
          </div>
        ) : null}

        <div className="text-muted-foreground absolute bottom-4 left-1/2 hidden -translate-x-1/2 items-center gap-4 text-[11px] sm:flex">
          <span>Drag to move</span>
          <span>Shift to constrain</span>
          <span>Double-click text to edit</span>
          <span className="flex items-center gap-1">
            <Copy className="size-3" /> ⌘C / ⌘V
          </span>
        </div>
      </section>

      <input
        ref={imageInputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp"
        className="sr-only"
        onChange={(event) => void handleImageFile(event.target.files?.[0])}
      />
    </main>
  );
}

function keepObjectOnCanvas(
  object: DrawingObject,
  document: DrawingDocument,
): DrawingObject {
  return {
    ...object,
    x: Math.max(0, Math.min(object.x, document.width - object.width)),
    y: Math.max(0, Math.min(object.y, document.height - object.height)),
  };
}
import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";
import { SiteConfig } from "@/site-config";
import {
  useAction as useConvexAction,
  useMutation as useConvexMutation,
  useQuery as useConvexQuery,
} from "convex/react";
import { AlertCircle, ArrowLeft } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";
import {
  createDrawingInspirationRef,
  drawingInspirationDetailRef,
  updateDrawingInspirationRef,
  uploadDrawingImageRef,
} from "./drawing.convex";
import { createEmptyDrawingDocument, type DrawingDocument } from "./drawing-document";
import { DrawingEditor } from "./drawing-editor";
import { exportDrawingDocumentToPngBlob } from "./drawing-renderer";

type DrawingInspirationPageProps = {
  orgSlug: string;
  inspirationId?: string;
  onCancel: () => void;
  onSaved: (inspirationId: string) => void;
};

export function DrawingInspirationPage({
  orgSlug,
  inspirationId,
  onCancel,
  onSaved,
}: DrawingInspirationPageProps) {
  const detail = useConvexQuery(
    drawingInspirationDetailRef,
    inspirationId ? { orgSlug, inspirationId } : "skip",
  );
  const createDrawing = useConvexMutation(createDrawingInspirationRef);
  const updateDrawing = useConvexMutation(updateDrawingInspirationRef);
  const uploadImage = useConvexAction(uploadDrawingImageRef);
  const [isSaving, setIsSaving] = useState(false);
  const [isUploadingImage, setIsUploadingImage] = useState(false);

  useEffect(() => {
    const previousTitle = document.title;
    document.title = SiteConfig.title;
    return () => {
      document.title = previousTitle;
    };
  }, []);

  const uploadDrawingFile = async (file: File) => {
    setIsUploadingImage(true);
    try {
      return await uploadImage({
        orgSlug,
        bytes: await file.arrayBuffer(),
        fileName: file.name,
        contentType: file.type || "image/png",
      });
    } finally {
      setIsUploadingImage(false);
    }
  };

  const saveDrawing = async (title: string, drawingDocument: DrawingDocument) => {
    setIsSaving(true);
    try {
      const previewBlob = await exportDrawingDocumentToPngBlob(drawingDocument);
      const previewUrl = await uploadImage({
        orgSlug,
        bytes: await previewBlob.arrayBuffer(),
        fileName: `drawing-preview-${inspirationId ?? Date.now()}.png`,
        contentType: "image/png",
      });

      const saved = inspirationId
        ? await updateDrawing({
            orgSlug,
            inspirationId,
            title,
            previewUrl,
            drawingDocument,
          })
        : await createDrawing({
            orgSlug,
            title,
            previewUrl,
            drawingDocument,
          });

      toast.success(inspirationId ? "Drawing updated" : "Drawing inspiration created");
      onSaved(saved.id);
    } finally {
      setIsSaving(false);
    }
  };

  if (inspirationId && detail === undefined) {
    return <DrawingPageLoading />;
  }

  if (inspirationId && detail instanceof Error) {
    return (
      <DrawingPageError message={detail.message} onCancel={onCancel} />
    );
  }

  if (inspirationId && !detail) {
    return (
      <DrawingPageError
        message="This drawing could not be loaded."
        onCancel={onCancel}
      />
    );
  }

  const initialDocument = detail?.drawingDocument ?? createEmptyDrawingDocument();
  const initialTitle = detail?.name ?? "Untitled drawing";

  return (
    <DrawingEditor
      key={detail?.updatedAt ?? "new-drawing"}
      initialDocument={initialDocument}
      initialTitle={initialTitle}
      isSaving={isSaving}
      isUploadingImage={isUploadingImage}
      onUploadImage={uploadDrawingFile}
      onSave={saveDrawing}
      onCancel={onCancel}
    />
  );
}

function DrawingPageLoading() {
  return (
    <main className="bg-muted fixed inset-0 z-50 flex items-center justify-center">
      <div className="bg-background flex items-center gap-3 rounded-xl px-5 py-4 shadow-[0_0_0_1px_rgba(0,0,0,0.08),0_12px_32px_rgba(0,0,0,0.08)]">
        <Spinner className="size-4" />
        <span className="text-sm">Loading drawing</span>
      </div>
    </main>
  );
}

function DrawingPageError({
  message,
  onCancel,
}: {
  message: string;
  onCancel: () => void;
}) {
  return (
    <main className="bg-muted fixed inset-0 z-50 flex items-center justify-center p-6">
      <div className="bg-background flex max-w-sm flex-col items-center rounded-xl p-6 text-center shadow-[0_0_0_1px_rgba(0,0,0,0.08),0_12px_32px_rgba(0,0,0,0.08)]">
        <AlertCircle className="text-destructive mb-3 size-6" />
        <p className="text-sm font-medium">Could not open drawing</p>
        <p className="text-muted-foreground mt-1 text-sm">{message}</p>
        <Button type="button" variant="outline" className="mt-5" onClick={onCancel}>
          <ArrowLeft className="size-4" />
          Return
        </Button>
      </div>
    </main>
  );
}

