        document.height,
      );
      preview(replaceObject(interaction.previous, nextObject));
      return;
    }

    if (interaction.kind === "resize") {
      const nextObject = resizeObjectFromCorner(
        interaction.origin,
        interaction.corner,
        point,
        event.shiftKey,
        document.width,
        document.height,
      );
      preview(replaceObject(interaction.previous, nextObject));
      return;
    }

    if (interaction.kind === "pencil") {
      const points = appendPencilPoint(
        interaction.points,
        point,
        event.shiftKey,
      );
      const nextInteraction = { ...interaction, points };
      setInteraction(nextInteraction);
      const pencilObject = createPencilObject(interaction.objectId, points);
      preview(replaceOrAppendObject(interaction.previous, pencilObject));
      return;
    }

    const constrainedPoint = constrainDrawPoint(
      interaction.start,
      point,
      interaction.tool,
      event.shiftKey,
    );
    const object = createDrawnObject(
      interaction.objectId,
      interaction.tool,
      interaction.start,
      constrainedPoint,
    );
    preview(replaceOrAppendObject(interaction.previous, object));
  };

  const finishInteraction = (event: ReactPointerEvent<SVGSVGElement>) => {
    if (!interaction || event.pointerId !== interaction.pointerId) return;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }

    const nextDocument = latestDocumentRef.current;
    onCommitDocument(interaction.previous, nextDocument);
    onSelectObject(interaction.objectId);
    if (interaction.kind === "draw" || interaction.kind === "pencil") {
      onToolChange("select");
    }
    setInteraction(null);
  };

  const commitTextDraft = () => {
    if (!editingText) {
      onFinishTextEditing();
      return;
    }
    const text = textDraft.trim() || "Text";
    const nextDocument = replaceObject(document, { ...editingText, text });
    onCommitDocument(document, nextDocument);
    onFinishTextEditing();
  };

  return (
    <div className="relative aspect-video w-full overflow-hidden rounded-lg bg-white shadow-[0_0_0_1px_rgba(0,0,0,0.12),0_18px_50px_rgba(0,0,0,0.12)] dark:shadow-[0_0_0_1px_rgba(255,255,255,0.12),0_18px_50px_rgba(0,0,0,0.35)]">
      <svg
        ref={svgRef}
        viewBox={`0 0 ${document.width} ${document.height}`}
        className={cn(
          "size-full select-none",
          tool === "select" ? "cursor-default" : "cursor-crosshair",
        )}
        style={{ background: document.background, touchAction: "none" }}
        role="application"
        aria-label="Thumbnail drawing canvas"
        onPointerDown={handleCanvasPointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={finishInteraction}
        onPointerCancel={finishInteraction}
      >
        {document.objects.map((object) => (
          <DrawingObjectView
            key={object.id}
            object={object}
            hidden={object.id === editingTextId}
            onPointerDown={(event) => handleObjectPointerDown(event, object)}
            onDoubleClick={(event) => {
              if (object.type !== "text") return;
              event.preventDefault();
              event.stopPropagation();
              onSelectObject(object.id);
              onStartTextEditing(object.id);
            }}
          />
        ))}

        {selectedObject && !editingTextId ? (
          <SelectionOutline
            object={selectedObject}
            onResizePointerDown={handleResizePointerDown}
          />
        ) : null}

        {editingText ? (
          <foreignObject
            x={editingText.x}
            y={editingText.y}
            width={Math.max(editingText.width, 120)}
            height={Math.max(editingText.height, 72)}
          >
            <textarea
              autoFocus
              value={textDraft}
              aria-label="Edit drawing text"
              className="size-full resize-none overflow-hidden rounded-md border-2 border-blue-500 bg-white/95 p-2 leading-[1.05] text-black outline-none"
              style={{
                color: editingText.color,
                fontFamily:
                  editingText.fontFamily === "display"
                    ? "ui-rounded, system-ui, sans-serif"
                    : "system-ui, sans-serif",
                fontSize: `${editingText.fontSize}px`,
                fontWeight: editingText.fontWeight === "bold" ? 700 : 400,
                textAlign: editingText.align,
              }}
              onChange={(event) => setTextDraft(event.target.value)}
              onBlur={commitTextDraft}
              onKeyDown={(event) => {
                if (event.key === "Escape") {
                  event.preventDefault();
                  event.stopPropagation();
                  commitTextDraft();
                }
                if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
                  event.preventDefault();
                  event.stopPropagation();
                  commitTextDraft();
                }
              }}
            />
          </foreignObject>
        ) : null}
      </svg>
    </div>
  );
}

function DrawingObjectView({
  object,
  hidden,
  onPointerDown,
  onDoubleClick,
}: {
  object: DrawingObject;
  hidden: boolean;
  onPointerDown: (event: ReactPointerEvent<SVGGElement>) => void;
  onDoubleClick: (event: ReactPointerEvent<SVGGElement>) => void;
}) {
  if (hidden) return null;

  return (
    <g
      opacity={object.opacity}
      onPointerDown={onPointerDown}
      onDoubleClick={onDoubleClick}
      style={{ cursor: "move" }}
      data-object-id={object.id}
    >
      {renderObject(object)}
    </g>
  );
}

function renderObject(object: DrawingObject) {
  if (object.type === "rect") {
    return (
      <rect
        x={object.x}
        y={object.y}
        width={object.width}
        height={object.height}
        rx={18}
        fill={object.fill}
        stroke={object.stroke}
        strokeWidth={object.strokeWidth}
        strokeLinejoin="round"
      />
    );
  }

  if (object.type === "ellipse") {
    return (
      <ellipse
        cx={object.x + object.width / 2}
        cy={object.y + object.height / 2}
        rx={object.width / 2}
        ry={object.height / 2}
        fill={object.fill}
        stroke={object.stroke}
        strokeWidth={object.strokeWidth}
      />
    );
  }

  if (object.type === "arrow") {
    const startX = object.x + object.startX * object.width;
    const startY = object.y + object.startY * object.height;
    const endX = object.x + object.endX * object.width;
    const endY = object.y + object.endY * object.height;
    const markerId = `arrowhead-${object.id.replace(/[^a-zA-Z0-9_-]/g, "")}`;
    return (
      <>
        <defs>
          <marker
            id={markerId}
            viewBox="0 0 12 12"
            refX="10"
            refY="6"
            markerWidth="9"
            markerHeight="9"
            orient="auto-start-reverse"
          >
            <path d="M 1 1 L 11 6 L 1 11 z" fill={object.stroke} />
          </marker>
        </defs>
        <line
          x1={startX}
          y1={startY}
          x2={endX}
          y2={endY}
          stroke={object.stroke}
          strokeWidth={object.strokeWidth}
          strokeLinecap="round"
          markerEnd={`url(#${markerId})`}
        />
      </>
    );
  }

  if (object.type === "pencil") {
    const points = object.points
      .map(
        (point) =>
          `${object.x + point.x * object.width},${object.y + point.y * object.height}`,
      )
      .join(" ");
    return (
      <polyline
        points={points}
        fill="none"
        stroke={object.stroke}
        strokeWidth={object.strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    );
  }

  if (object.type === "text") {
    const justifyContent =
      object.align === "center"
        ? "center"
        : object.align === "right"
          ? "flex-end"
          : "flex-start";
    return (
      <foreignObject
        x={object.x}
        y={object.y}
        width={object.width}
        height={object.height}
        pointerEvents="all"
      >
        <div
          style={{
            alignItems: "center",
            color: object.color,
            display: "flex",
            fontFamily:
              object.fontFamily === "display"
                ? "ui-rounded, system-ui, sans-serif"
                : "system-ui, sans-serif",
            fontSize: `${object.fontSize}px`,
            fontWeight: object.fontWeight === "bold" ? 700 : 400,
            height: "100%",
            justifyContent,
            lineHeight: 1.05,
            overflow: "hidden",
            textAlign: object.align,
            whiteSpace: "pre-wrap",
            width: "100%",
            wordBreak: "break-word",
          }}
        >
          {object.text}
        </div>
      </foreignObject>
    );
  }

  if (object.type === "image") {
    return (
      <>
        <image
          href={object.src}
          x={object.x}
          y={object.y}
          width={object.width}
          height={object.height}
          preserveAspectRatio={
            object.fit === "cover" ? "xMidYMid slice" : "xMidYMid meet"
          }
        />
        <rect
          x={object.x}
          y={object.y}
          width={object.width}
          height={object.height}
          fill="none"
          stroke="rgba(0,0,0,0.1)"
          strokeWidth={2}
          pointerEvents="none"
        />
      </>
    );
  }

  const centerX = object.x + object.width / 2;
  const headRadius = Math.min(object.width, object.height) * 0.18;
  const headY = object.y + object.height * 0.27;
  const bodyTop = headY + headRadius * 1.35;
  const bodyBottom = object.y + object.height * 0.9;
  const bodyHalfWidth = object.width * 0.38;
  return (
    <>
      <ellipse
        cx={centerX}
        cy={headY}
        rx={headRadius}
        ry={headRadius * 1.08}
        fill={object.fill}
        stroke={object.stroke}
        strokeWidth={5}
      />
      <path
        d={`M ${centerX - bodyHalfWidth} ${bodyBottom} Q ${centerX - bodyHalfWidth * 0.8} ${bodyTop} ${centerX} ${bodyTop} Q ${centerX + bodyHalfWidth * 0.8} ${bodyTop} ${centerX + bodyHalfWidth} ${bodyBottom} Z`}
        fill={object.fill}
        stroke={object.stroke}
        strokeWidth={5}
        strokeLinejoin="round"
      />
      <text
        x={centerX}
        y={object.y + object.height - 12}
        textAnchor="middle"
        fontSize={22}
        fontFamily="system-ui, sans-serif"
        fontWeight={600}
        fill={object.stroke}
      >
        {object.label}
      </text>
    </>
  );
}

