import { v } from "convex/values";

const drawingObjectBase = {
  id: v.string(),
  x: v.number(),
  y: v.number(),
  width: v.number(),
  height: v.number(),
  opacity: v.number(),
};

const shapeStyle = {
  fill: v.string(),
  stroke: v.string(),
  strokeWidth: v.number(),
};

const rectangleValidator = v.object({
  ...drawingObjectBase,
  ...shapeStyle,
  type: v.literal("rect"),
});

const ellipseValidator = v.object({
  ...drawingObjectBase,
  ...shapeStyle,
  type: v.literal("ellipse"),
});

const arrowValidator = v.object({
  ...drawingObjectBase,
  type: v.literal("arrow"),
  stroke: v.string(),
  strokeWidth: v.number(),
  startX: v.number(),
  startY: v.number(),
  endX: v.number(),
  endY: v.number(),
});

const textValidator = v.object({
  ...drawingObjectBase,
  type: v.literal("text"),
  text: v.string(),
  fontSize: v.number(),
  fontFamily: v.union(v.literal("sans"), v.literal("display")),
  fontWeight: v.union(v.literal("normal"), v.literal("bold")),
  align: v.union(
    v.literal("left"),
    v.literal("center"),
    v.literal("right"),
  ),
  color: v.string(),
});

const pencilValidator = v.object({
  ...drawingObjectBase,
  type: v.literal("pencil"),
  points: v.array(
    v.object({
      x: v.number(),
      y: v.number(),
    }),
  ),
  stroke: v.string(),
  strokeWidth: v.number(),
});

const imageValidator = v.object({
  ...drawingObjectBase,
  type: v.literal("image"),
  src: v.string(),
  alt: v.string(),
  fit: v.union(v.literal("cover"), v.literal("contain")),
});

const personValidator = v.object({
  ...drawingObjectBase,
  type: v.literal("person"),
  label: v.string(),
  fill: v.string(),
  stroke: v.string(),
});

export const drawingObjectValidator = v.union(
  rectangleValidator,
  ellipseValidator,
  arrowValidator,
  textValidator,
  pencilValidator,
  imageValidator,
  personValidator,
);

export const drawingDocumentValidator = v.object({
  version: v.literal(1),
  width: v.literal(1280),
  height: v.literal(720),
  background: v.string(),
  objects: v.array(drawingObjectValidator),
});
