   498	export async function renderDrawingDocumentToCanvas(
   499	  input: DrawingDocument,
   500	  options: DrawingRenderOptions = {},
   501	): Promise<HTMLCanvasElement> {
   502	  const document = parseDrawingDocument(input);
   503	  const pixelRatio = options.pixelRatio ?? 1;
   504	  const imageTimeoutMs = options.imageTimeoutMs ?? DEFAULT_IMAGE_TIMEOUT_MS;
   505	
   506	  if (!Number.isFinite(pixelRatio) || pixelRatio <= 0) {
   507	    throw new Error("Drawing pixel ratio must be a positive number");
   508	  }
   509	  if (!Number.isFinite(imageTimeoutMs) || imageTimeoutMs < 0) {
   510	    throw new Error("Drawing image timeout must be a non-negative number");
   511	  }
   512	
   513	  const canvas = options.canvas ?? window.document.createElement("canvas");
   514	  canvas.width = Math.round(document.width * pixelRatio);
   515	  canvas.height = Math.round(document.height * pixelRatio);
   516	
   517	  const context = canvas.getContext("2d");
   518	  if (!context) {
   519	    throw new Error("Canvas 2D rendering is not available");
   520	  }
   521	
   522	  const images = await loadDocumentImages(
   523	    document.objects,
   524	    imageTimeoutMs,
   525	    options.renderImages ?? true,
   526	  );
   527	
   528	  context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
   529	  context.imageSmoothingEnabled = true;
   530	  context.imageSmoothingQuality = "high";
   531	  context.fillStyle = document.background;
   532	  context.fillRect(0, 0, document.width, document.height);
   533	
   534	  for (const object of document.objects) {
   535	    drawObject(context, object, images);
   536	  }
   537	
   538	  return canvas;
   539	}
