  const width = Math.max(MIN_OBJECT_SIZE, maxX - minX);
  const height = Math.max(MIN_OBJECT_SIZE, maxY - minY);
  const points: DrawingPoint[] = sourcePoints.map((point) => ({
    x: (point.x - minX) / width,
    y: (point.y - minY) / height,
  }));

  return {
    id,
    type: "pencil",
    x: minX,
    y: minY,
