  const setColor = (color: string) => {
    if (object.type === "text") {
      onChange({ ...object, color });
    } else if (object.type === "arrow" || object.type === "pencil") {
      onChange({ ...object, stroke: color });
    } else if (
      object.type === "rect" ||
      object.type === "ellipse" ||
      object.type === "person"
    ) {
      onChange({ ...object, fill: color });
    }
  };

  const activeColor =
    object.type === "text"
      ? object.color
      : object.type === "arrow" || object.type === "pencil"
        ? object.stroke
