          <Button
            type="button"
            size="icon"
            variant="ghost"
            className="text-destructive hover:text-destructive size-9 transition-transform active:scale-[0.96]"
            aria-label="Delete selected object"
            onClick={onDelete}
          >
            <Trash2 className="size-3.5" />
