function isAdminDebugOnboardingSearch(searchStr: string) {
  const value = new URLSearchParams(searchStr).get("adminDebug");
  return value === "1" || value === "true";
}

function isDrawingEditorLocation(pathname: string, searchStr: string) {
  if (new URLSearchParams(searchStr).get("mode") !== "drawing") return false;

  return (
    pathname.endsWith("/inspirations/new") ||
    /\/inspirations\/[^/]+$/.test(pathname)
  );
}

